[metadata] {"type": "create", "filePath": "/app/output/index.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>GreenBean Coffee — Your Daily Coffee Ritual</title>
  <link rel="preconnect" href="https://fonts.googleapis.com">
  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
  <link href="https://fonts.googleapis.com/css2?family=Fredoka:wght@400;500;600;700&family=Nunito:wght@300;400;500;600;700&display=swap" rel="stylesheet">
  <style>
    *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

    :root {
      --green: #00824A;
      --green-dark: #006B3A;
      --forest: #32462F;
      --cream: #F3CEA1;
      --cream-light: #FDF6E8;
      --brown: #5D4037;
      --brown-light: #8D6E63;
      --white: #FFFFFF;
      --gray-50: #F9FAFB;
      --gray-100: #F3F4F6;
      --gray-200: #E5E7EB;
      --gray-300: #D1D5DB;
      --gray-400: #9CA3AF;
      --gray-500: #6B7280;
      --gray-600: #4B5563;
      --gray-700: #374151;
      --gray-800: #1F2937;
      --gray-900: #111827;
      --shadow-sm: 0 1px 2px rgba(0,0,0,0.05);
      --shadow-md: 0 4px 6px -1px rgba(0,0,0,0.1), 0 2px 4px -2px rgba(0,0,0,0.1);
      --shadow-lg: 0 10px 15px -3px rgba(0,0,0,0.1), 0 4px 6px -4px rgba(0,0,0,0.1);
      --shadow-xl: 0 20px 25px -5px rgba(0,0,0,0.1), 0 8px 10px -6px rgba(0,0,0,0.1);
      --radius-sm: 8px;
      --radius-md: 12px;
      --radius-lg: 16px;
      --radius-xl: 24px;
      --transition: 200ms ease-out;
    }

    body {
      font-family: 'Nunito', -apple-system, BlinkMacSystemFont, sans-serif;
      background: var(--cream-light);
      color: var(--gray-800);
      line-height: 1.6;
      -webkit-font-smoothing: antialiased;
    }

    h1, h2, h3, h4, h5, h6 {
      font-family: 'Fredoka', 'Nunito', sans-serif;
      font-weight: 600;
      line-height: 1.2;
    }

    a { text-decoration: none; color: inherit; }
    button { font-family: inherit; cursor: pointer; border: none; background: none; }
    img { max-width: 100%; height: auto; display: block; }

    /* Header */
    .header {
      background: var(--white);
      box-shadow: var(--shadow-sm);
      position: sticky;
      top: 0;
      z-index: 100;
    }

    .header-inner {
      max-width: 1280px;
      margin: 0 auto;
      padding: 0 24px;
      display: flex;
      align-items: center;
      justify-content: space-between;
      height: 72px;
    }

    .logo {
      display: flex;
      align-items: center;
      gap: 10px;
      font-family: 'Fredoka', sans-serif;
      font-weight: 700;
      font-size: 24px;
      color: var(--green);
    }

    .logo-icon {
      width: 40px;
      height: 40px;
      background: var(--green);
      border-radius: 50%;
      display: flex;
      align-items: center;
      justify-content: center;
    }

    .logo-icon svg { width: 24px; height: 24px; fill: var(--white); }

    .nav-main {
      display: flex;
      align-items: center;
      gap: 32px;
    }

    .nav-link {
      font-weight: 600;
      font-size: 15px;
      color: var(--gray-700);
      padding: 8px 0;
      position: relative;
      transition: color var(--transition);
    }

    .nav-link::after {
      content: '';
      position: absolute;
      bottom: 4px;
      left: 0;
      right: 0;
      height: 2px;
      background: var(--green);
      transform: scaleX(0);
      transition: transform var(--transition);
    }

    .nav-link:hover { color: var(--green); }
    .nav-link:hover::after { transform: scaleX(1); }

    .nav-actions {
      display: flex;
      align-items: center;
      gap: 16px;
    }

    .btn {
      display: inline-flex;
      align-items: center;
      justify-content: center;
      gap: 8px;
      padding: 10px 20px;
      font-weight: 600;
      font-size: 15px;
      border-radius: var(--radius-md);
      transition: all var(--transition);
    }

    .btn-ghost {
      color: var(--gray-700);
    }

    .btn-ghost:hover {
      background: var(--gray-100);
    }

    .btn-primary {
      background: var(--green);
      color: var(--white);
    }

    .btn-primary:hover {
      background: var(--green-dark);
      transform: translateY(-1px);
      box-shadow: var(--shadow-md);
    }

    .btn-secondary {
      background: var(--cream);
      color: var(--forest);
    }

    .btn-secondary:hover {
      background: #EBC48F;
    }

    /* Mobile menu */
    .mobile-menu-btn {
      display: none;
      padding: 8px;
    }

    .mobile-menu-btn svg { width: 24px; height: 24px; stroke: var(--gray-700); }

    @media (max-width: 768px) {
      .nav-main { display: none; }
      .nav-actions { display: none; }
      .mobile-menu-btn { display: flex; }
    }

    /* Cookie Banner */
    .cookie-banner {
      position: fixed;
      bottom: 0;
      left: 0;
      right: 0;
      background: var(--forest);
      color: var(--white);
      padding: 20px 24px;
      z-index: 200;
      transform: translateY(100%);
      transition: transform 300ms ease-out;
    }

    .cookie-banner.show { transform: translateY(0); }

    .cookie-inner {
      max-width: 1280px;
      margin: 0 auto;
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 24px;
    }

    .cookie-text { font-size: 14px; opacity: 0.9; }

    .cookie-actions {
      display: flex;
      gap: 12px;
      flex-shrink: 0;
    }

    .cookie-actions .btn {
      padding: 8px 16px;
      font-size: 14px;
    }

    .btn-outline {
      border: 1px solid rgba(255,255,255,0.4);
      color: var(--white);
    }

    .btn-outline:hover {
      background: rgba(255,255,255,0.1);
    }

    /* Hero */
    .hero {
      background: linear-gradient(135deg, var(--green) 0%, var(--forest) 100%);
      color: var(--white);
      padding: 80px 24px;
      position: relative;
      overflow: hidden;
    }

    .hero::before {
      content: '';
      position: absolute;
      top: -50%;
      right: -20%;
      width: 600px;
      height: 600px;
      background: radial-gradient(circle, rgba(255,255,255,0.1) 0%, transparent 70%);
      border-radius: 50%;
    }

    .hero-inner {
      max-width: 1280px;
      margin: 0 auto;
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 48px;
      align-items: center;
      position: relative;
    }

    .hero-content { }

    .hero h1 {
      font-size: clamp(36px, 5vw, 56px);
      margin-bottom: 20px;
      font-weight: 700;
    }

    .hero p {
      font-size: 18px;
      opacity: 0.9;
      margin-bottom: 32px;
      max-width: 480px;
    }

    .hero-actions {
      display: flex;
      gap: 16px;
      flex-wrap: wrap;
    }

    .hero-visual {
      position: relative;
      display: flex;
      justify-content: center;
    }

    .hero-image {
      width: 100%;
      max-width: 500px;
      aspect-ratio: 4/3;
      background: linear-gradient(145deg, rgba(255,255,255,0.15) 0%, rgba(255,255,255,0.05) 100%);
      border-radius: var(--radius-xl);
      display: flex;
      align-items: center;
      justify-content: center;
      backdrop-filter: blur(10px);
    }

    .hero-image-placeholder {
      width: 80%;
      height: 80%;
      background: rgba(255,255,255,0.2);
      border-radius: var(--radius-lg);
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 14px;
      opacity: 0.7;
    }

    @media (max-width: 968px) {
      .hero-inner { grid-template-columns: 1fr; text-align: center; }
      .hero p { margin-left: auto; margin-right: auto; }
      .hero-actions { justify-content: center; }
      .hero-visual { order: -1; }
      .hero-image { max-width: 400px; }
    }

    /* Section styles */
    .section {
      padding: 64px 24px;
    }

    .section-inner {
      max-width: 1280px;
      margin: 0 auto;
    }

    .section-header {
      text-align: center;
      margin-bottom: 48px;
    }

    .section-header h2 {
      font-size: clamp(28px, 4vw, 40px);
      color: var(--forest);
      margin-bottom: 12px;
    }

    .section-header p {
      font-size: 18px;
      color: var(--gray-500);
      max-width: 600px;
      margin: 0 auto;
    }

    /* Featured Product */
    .featured-product {
      background: var(--white);
    }

    .featured-card {
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 48px;
      align-items: center;
      background: linear-gradient(135deg, #FF6B35 0%, #F7931E 100%);
      border-radius: var(--radius-xl);
      padding: 48px;
      color: var(--white);
      overflow: hidden;
      position: relative;
    }

    .featured-card::before {
      content: '';
      position: absolute;
      top: -100px;
      right: -100px;
      width: 300px;
      height: 300px;
      background: rgba(255,255,255,0.1);
      border-radius: 50%;
    }

    .featured-content { position: relative; }

    .featured-tag {
      display: inline-block;
      background: rgba(255,255,255,0.2);
      padding: 6px 14px;
      border-radius: 20px;
      font-size: 13px;
      font-weight: 600;
      margin-bottom: 16px;
    }

    .featured-card h2 {
      font-size: clamp(28px, 4vw, 40px);
      margin-bottom: 16px;
    }

    .featured-card p {
      font-size: 16px;
      opacity: 0.9;
      margin-bottom: 24px;
      line-height: 1.7;
    }

    .featured-visual {
      position: relative;
      display: flex;
      justify-content: center;
    }

    .featured-image {
      width: 100%;
      max-width: 380px;
      aspect-ratio: 1;
      background: rgba(255,255,255,0.2);
      border-radius: var(--radius-xl);
      display: flex;
      align-items: center;
      justify-content: center;
      backdrop-filter: blur(5px);
    }

    .featured-image-placeholder {
      font-size: 14px;
      opacity: 0.7;
    }

    @media (max-width: 868px) {
      .featured-card { grid-template-columns: 1fr; text-align: center; padding: 40px 32px; }
      .featured-visual { order: -1; }
      .featured-image { max-width: 280px; margin: 0 auto; }
    }

    /* Promo Grid */
    .promo-grid {
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: 24px;
    }

    @media (max-width: 968px) {
      .promo-grid { grid-template-columns: 1fr; }
    }

    .promo-card {
      background: var(--white);
      border-radius: var(--radius-lg);
      padding: 32px;
      box-shadow: var(--shadow-sm);
      transition: all var(--transition);
    }

    .promo-card:hover {
      transform: translateY(-4px);
      box-shadow: var(--shadow-lg);
    }

    .promo-icon {
      width: 56px;
      height: 56px;
      background: var(--cream);
      border-radius: var(--radius-md);
      display: flex;
      align-items: center;
      justify-content: center;
      margin-bottom: 20px;
    }

    .promo-icon svg { width: 28px; height: 28px; stroke: var(--green); }

    .promo-card h3 {
      font-size: 22px;
      color: var(--forest);
      margin-bottom: 12px;
    }

    .promo-card p {
      font-size: 15px;
      color: var(--gray-500);
      margin-bottom: 20px;
      line-height: 1.6;
    }

    /* Seasonal Highlights */
    .seasonal-section { background: var(--cream-light); }

    .seasonal-grid {
      display: grid;
      grid-template-columns: repeat(2, 1fr);
      gap: 32px;
    }

    @media (max-width: 768px) {
      .seasonal-grid { grid-template-columns: 1fr; }
    }

    .seasonal-card {
      background: var(--white);
      border-radius: var(--radius-xl);
      overflow: hidden;
      box-shadow: var(--shadow-md);
      transition: all var(--transition);
    }

    .seasonal-card:hover {
      transform: translateY(-4px);
      box-shadow: var(--shadow-xl);
    }

    .seasonal-image {
      height: 220px;
      background: linear-gradient(135deg, var(--green) 0%, var(--forest) 100%);
      display: flex;
      align-items: center;
      justify-content: center;
      color: var(--white);
      font-size: 14px;
      opacity: 0.7;
    }

    .seasonal-card:nth-child(2) .seasonal-image {
      background: linear-gradient(135deg, #9B59B6 0%, #8E44AF 100%);
    }

    .seasonal-content { padding: 28px; }

    .seasonal-card h3 {
      font-size: 24px;
      color: var(--forest);
      margin-bottom: 12px;
    }

    .seasonal-card p {
      font-size: 15px;
      color: var(--gray-500);
      margin-bottom: 20px;
      line-height: 1.6;
    }

    /* Nondairy Promo */
    .nondairy-promo {
      background: linear-gradient(135deg, var(--forest) 0%, #1E3A1F 100%);
      color: var(--white);
    }

    .nondairy-inner {
      display: flex;
      align-items: center;
      gap: 48px;
    }

    .nondairy-content { flex: 1; }

    .nondairy-content h2 {
      font-size: clamp(28px, 4vw, 40px);
      margin-bottom: 16px;
    }

    .nondairy-content p {
      font-size: 18px;
      opacity: 0.9;
      margin-bottom: 28px;
      line-height: 1.7;
    }

    .nondairy-visual {
      flex: 1;
      display: flex;
      justify-content: center;
    }

    .nondairy-image {
      width: 100%;
      max-width: 400px;
      aspect-ratio: 4/3;
      background: rgba(255,255,255,0.1);
      border-radius: var(--radius-xl);
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 14px;
      opacity: 0.6;
    }

    @media (max-width: 768px) {
      .nondairy-inner { flex-direction: column; text-align: center; }
    }

    /* Footer */
    .footer {
      background: var(--forest);
      color: var(--white);
      padding: 64px 24px 32px;
    }

    .footer-inner {
      max-width: 1280px;
      margin: 0 auto;
    }

    .footer-grid {
      display: grid;
      grid-template-columns: repeat(5, 1fr);
      gap: 40px;
      margin-bottom: 48px;
    }

    @media (max-width: 968px) {
      .footer-grid { grid-template-columns: repeat(3, 1fr); }
    }

    @media (max-width: 600px) {
      .footer-grid { grid-template-columns: 1fr 1fr; }
      .footer-accordion-content { display: none; }
      .footer-accordion.open .footer-accordion-content { display: block; }
    }

    .footer-section h4 {
      font-family: 'Fredoka', sans-serif;
      font-size: 16px;
      font-weight: 600;
      margin-bottom: 20px;
      cursor: pointer;
    }

    @media (min-width: 601px) {
      .footer-section h4 { cursor: default; }
    }

    .footer-links {
      list-style: none;
    }

    .footer-links li { margin-bottom: 10px; }

    .footer-links a {
      font-size: 14px;
      opacity: 0.8;
      transition: opacity var(--transition);
    }

    .footer-links a:hover { opacity: 1; }

    .footer-bottom {
      border-top: 1px solid rgba(255,255,255,0.1);
      padding-top: 32px;
      display: flex;
      align-items: center;
      justify-content: space-between;
      flex-wrap: wrap;
      gap: 16px;
    }

    .footer-logo {
      font-family: 'Fredoka', sans-serif;
      font-weight: 700;
      font-size: 20px;
      color: var(--cream);
    }

    .footer-legal {
      font-size: 13px;
      opacity: 0.6;
    }

    .footer-social {
      display: flex;
      gap: 16px;
    }

    .footer-social a {
      width: 40px;
      height: 40px;
      background: rgba(255,255,255,0.1);
      border-radius: 50%;
      display: flex;
      align-items: center;
      justify-content: center;
      transition: background var(--transition);
    }

    .footer-social a:hover { background: rgba(255,255,255,0.2); }

    .footer-social svg { width: 20px; height: 20px; fill: var(--white); }

    /* Reduced motion */
    @media (prefers-reduced-motion: reduce) {
      *, *::before, *::after {
        animation-duration: 0.01ms !important;
        transition-duration: 0.01ms !important;
      }
    }
  </style>
</head>
<body>

  <!-- Header -->
  <header class="header">
    <div class="header-inner">
      <a href="index.html" class="logo">
        <div class="logo-icon">
          <svg viewBox="0 0 24 24"><path d="M18 8h1c.55 0 1-.45 1-1V5c0-.55-.45-1-1-1h-1c-.55 0-1 .45-1 1v2c0 .55.45 1 1 1zm-1 8h-4v2h4v-2zm-5-6h1V5h-1v2H8V5H7v2H6V5c0-.55.45-1 1-1h1c.55 0 1 .45 1 1v2h4V5c0-.55.45-1 1-1h1c.55 0 1 .45 1 1v2h1c.55 0 1 .45 1 1v7c0 2.76-2.24 5-5 5s-5-2.24-5-5V9c0-.55-.45-1-1-1H8c-.55 0-1 .45-1 1v2z"/></svg>
        </div>
        GreenBean
      </a>
      <nav class="nav-main">
        <a href="menu.html" class="nav-link">Menu</a>
        <a href="rewards.html" class="nav-link">Rewards</a>
        <a href="gift.html" class="nav-link">Gift Cards</a>
        <a href="store-locator.html" class="nav-link">Find a store</a>
      </nav>
      <div class="nav-actions">
        <a href="#" class="btn btn-ghost">Sign in</a>
        <a href="#" class="btn btn-primary">Join now</a>
      </div>
      <button class="mobile-menu-btn" aria-label="Open menu">
        <svg viewBox="0 0 24 24" fill="none" stroke-width="2" stroke-linecap="round"><path d="M3 12h18M3 6h18M3 18h18"/></svg>
      </button>
    </div>
  </header>

  <!-- Hero -->
  <section class="hero">
    <div class="hero-inner">
      <div class="hero-content">
        <h1>It's a great day for coffee</h1>
        <p>Start your morning right with handcrafted beverages made from the finest beans. Order ahead, skip the line.</p>
        <div class="hero-actions">
          <a href="#" class="btn btn-secondary">Start an order</a>
          <a href="menu.html" class="btn btn-outline" style="border: 2px solid rgba(255,255,255,0.4); color: white;">View menu</a>
        </div>
      </div>
      <div class="hero-visual">
        <div class="hero-image">
          <div class="hero-image-placeholder">[Coffee lifestyle imagery]<br>Latte art, cozy cafe vibes</div>
        </div>
      </div>
    </div>
  </section>

  <!-- Featured Product -->
  <section class="section featured-product">
    <div class="section-inner">
      <div class="featured-card">
        <div class="featured-content">
          <span class="featured-tag">New</span>
          <h2>New Citrus Energy Refreshers just dropped</h2>
          <p>Introducing a new kind of energy. Now you can enjoy the Refreshers you love with extra caffeine from nature and a B-vitamin boost.</p>
          <a href="menu.html" class="btn btn-primary" style="background: white; color: #FF6B35;">Give them a try</a>
        </div>
        <div class="featured-visual">
          <div class="featured-image">
            <div class="featured-image-placeholder">[Citrus Energy<br>Refreshers]</div>
          </div>
        </div>
      </div>
    </div>
  </section>

  <!-- Afternoon Promo -->
  <section class="section" style="background: var(--gray-50);">
    <div class="section-inner">
      <div class="promo-grid">
        <div class="promo-card">
          <div class="promo-icon">
            <svg viewBox="0 0 24 24" fill="none" stroke-width="2" stroke-linecap="round"><circle cx="12" cy="12" r="10"/><path d="M12 6v6l4 2"/></svg>
          </div>
          <h3>Your afternoon reset</h3>
          <p>When 2 p.m. hits and you need a little boost, we've got you covered — with tasty drinks, snacks and sweet treats to keep the good vibes going.</p>
          <a href="menu.html" class="btn btn-secondary">Explore our afternoon menu</a>
        </div>
        <div class="promo-card">
          <div class="promo-icon">
            <svg viewBox="0 0 24 24" fill="none" stroke-width="2" stroke-linecap="round"><path d="M12 2a10 10 0 1 0 10 10A10 10 0 0 0 12 2zm0 18a8 8 0 1 1 8-8 8 8 0 0 1-8 8z"/><path d="M12 6v6l4 2"/></svg>
          </div>
          <h3>Inspire your next order with ChatGPT</h3>
          <p>Discover drinks that fit your mood, goals and preferences in just a few conversational prompts.</p>
          <a href="#" class="btn btn-secondary">Learn more</a>
        </div>
        <div class="promo-card">
          <div class="promo-icon">
            <svg viewBox="0 0 24 24" fill="none" stroke-width="2" stroke-linecap="round"><path d="M12 2v20M17 5H9.5a3.5 3.5 0 0 0 0 7h5a3.5 3.5 0 0 1 0 7H6"/></svg>
          </div>
          <h3>Nondairy, No extra</h3>
          <p>Enjoy your beverage with your choice of nondairy milk — like oat, almond, coconut or soy — for no additional charge.</p>
          <a href="menu.html" class="btn btn-secondary">Start an order</a>
        </div>
      </div>
    </div>
  </section>

  <!-- Seasonal Highlights -->
  <section class="section seasonal-section">
    <div class="section-inner">
      <div class="section-header">
        <h2>Seasonal Favorites</h2>
        <p>Limited-time flavors to brighten your day</p>
      </div>
      <div class="seasonal-grid">
        <div class="seasonal-card">
          <div class="seasonal-image">[Iced Mango Cream Matcha & Chai]</div>
          <div class="seasonal-content">
            <h3>A new fruity twist is here</h3>
            <p>Introducing vibrant Iced Mango Cream Matcha and rich Iced Mango Cream Chai. Topped with velvety mango cream cold foam for a delicious pop of sweetness, sip after sip.</p>
            <a href="menu.html" class="btn btn-primary">Order now</a>
          </div>
