      font-size: 14px;
      color: var(--gray-500);
      padding: 8px 0;
      padding-left: 20px;
      position: relative;
    }

    .terms li::before {
      content: '•';
      position: absolute;
      left: 0;
      color: var(--green);
    }

    .terms-toggle {
      display: flex;
      align-items: center;
      gap: 8px;
      font-weight: 600;
      color: var(--forest);
      cursor: pointer;
      padding: 16px 0;
      border-top: 1px solid var(--gray-200);
      width: 100%;
      background: none;
      text-align: left;
    }

    .terms-toggle svg { width: 20px; height: 20px; transition: transform var(--transition); }
    .terms-toggle.open svg { transform: rotate(180deg); }

    .terms-content {
      display: none;
      padding-bottom: 24px;
    }

    .terms-content.open { display: block; }

    /* Footer */
    .footer {
      background: var(--forest);
      color: var(--white);
      padding: 64px 24px 32px;
