  <script>
    // Featured carousel
    let featuredPos = 0;
    const featuredCards = 7;

    function slideCarousel(carousel, direction) {
      const track = document.getElementById(carousel + 'Track');
      if (!track) return;

      const cards = track.children;
      const cardWidth = cards[0].offsetWidth + 24; // card width + gap
      const visibleCards = Math.floor(track.parentElement.offsetWidth / cardWidth) || 4;
      const maxPos = cards.length - visibleCards;

      if (carousel === 'featured') {
        featuredPos = Math.max(0, Math.min(maxPos, featuredPos + direction));
        track.style.transform = `translateX(-${featuredPos * cardWidth}px)`;
      } else {
        // Category carousels
        const stateKey = carousel + 'Pos';
        if (!window[stateKey]) window[stateKey] = 0;
        window[stateKey] = Math.max(0, Math.min(maxPos, window[stateKey] + direction));
        track.style.transform = `translateX(-${window[stateKey] * cardWidth}px)`;
      }
    }

    function toggleFaq(btn) {
      const item = btn.closest('.faq-item');
      item.classList.toggle('open');
    }

    function toggleAccordion(el) {
      if (window.innerWidth > 600) return;
      const section = el.closest('.footer-accordion');
      section.classList.toggle('open');
    }
  </script>

