  <script>
    let currentOrderType = 'pickup';

    function setOrderType(type) {
      currentOrderType = type;
      document.querySelectorAll('.order-type-btn').forEach(btn => {
        btn.classList.toggle('active', btn.textContent.toLowerCase() === type);
      });
    }

    function showSuggestions(value) {
      const suggestions = document.getElementById('suggestions');
      if (value.length > 0) {
        suggestions.classList.add('show');
      } else {
        suggestions.classList.remove('show');
      }
    }

    function hideSuggestions() {
      setTimeout(() => {
        document.getElementById('suggestions').classList.remove('show');
      }, 200);
    }

    function selectSuggestion(text) {
      document.getElementById('searchInput').value = text;
      document.getElementById('suggestions').classList.remove('show');
    }

    function toggleFilter() {
      document.getElementById('filterPanel').classList.toggle('show');
    }

    function toggleChip(chip) {
      chip.classList.toggle('active');
    }

    function selectStore(element, name) {
      document.querySelectorAll('.result-item').forEach(item => item.classList.remove('selected'));
      element.classList.add('selected');

      document.querySelectorAll('.map-pin').forEach(pin => pin.classList.remove('selected'));
      const pins = document.querySelectorAll('.map-pin');
      const index = Array.from(document.querySelectorAll('.result-item')).indexOf(element);
      if (pins[index]) pins[index].classList.add('selected');

      document.querySelector('.map-info-name').textContent = name;
    }

    function toggleAccordion(el) {
      if (window.innerWidth > 600) return;
      const section = el.closest('.footer-accordion');
      section.classList.toggle('open');
    }
  </script>

